startup6484:
function startupPrompt() {
  // Allowance for the one-time startup message: the provider's startup budget, else its send budget, else a safe 50,000
  // (a missing value must never mean "unlimited"). A user's own message-cap setting still wins; "off" means no cap.
  const providerStartCap = P.startupCharBudget || P.sendCharBudget || 50000;
  const startCap = ZS.limits ? ZS.limits.sendBudget(providerStartCap) : providerStartCap;
  const baseLen = systemPrompt().length + 1500; // transport-check text and slack
  // Kept small on purpose: a huge first message is slow for every site to accept and was the main cause of failed sends. Per-task rules still arrive in full through the director.
  const fullBudget = Math.min(22000, startCap - baseLen - 4000);
  return systemPrompt({ full: true, fullBudget }) + "\n\n[STARTUP TRANSPORT CHECK]\nThis turn initializes Multi-Script; do not begin building, researching or critiquing anything yet. First emit exactly {\"command\":\"list_commands\",\"params\":{}}. After the real catalog result, acknowledge readiness and wait for the user's task. Keep every local command as ordinary reply JSON, never a native provider tool call.";
}
